import pg from "pg";
import pgvector from "pgvector/pg";

const client = new pg.Client({ database: "app" });
await client.connect();
await pgvector.registerTypes(client);
const { rows } = await client.query("SELECT body FROM docs ORDER BY embedding <=> $1 LIMIT 1", [pgvector.toSql([0.1, 0.8, 0.1])]);
console.log(rows);
